import pickle
N=14; R=7
W={}
for n in range(N+1):
 for r in range(min(n,R)+1):
  if r==n:
   W[n,r]=set(range(2**n+1));continue
  if r==0:
   W[n,r]={0,2**n};continue
  s={0,2**n}
  s.update(2*w for w in W[n-1,min(r,n-1)])
  v=W[n-1,r-1]
  s.update(a+b for a in v for b in v)
  for n1 in range(1,n//2+1):
   n2=n-n1
   for r1 in range(min(r,n1)+1):
    for r2 in range(min(r,n2)+1):
     a1=W[n1,r1];a2=W[n2,r2]
     if r1+r2<=r:s.update(a*b for a in a1 for b in a2)
     if r1==min(r,n1) and r2==min(r,n2):s.update(a*2**n2+b*2**n1-2*a*b for a in a1 for b in a2)
  W[n,r]=s
pickle.dump(W,open('weights.pkl','wb'))
s=W[14,7]
print('missing <=512:',[x for x in range(0,514,2) if x not in s])
print('middle missing',len(set(range(512,16384-510,2))-s))
print('present <=400',sorted(x for x in s if x<=400))

