import random,pickle,time
n=14;r=7;known={272,288,296,304,308,312,314,316,318}
for t in [1,2,3]:
 A=set(range(5));B=set(range(5-t))|set(range(5,5+t))
 tables=[]
 for fixed in [A,B]:
  free=sorted(set(range(n))-fixed);points=[]
  for x in range(512):points.append(sum(((x>>i)&1)<<j for i,j in enumerate(free))+sum(1<<j for j in fixed))
  ls=[]
  for mask in range(1,512):
   v=0
   for x,p in enumerate(points):
    if (x&mask).bit_count()%2:v|=1<<p
   ls.append(v)
  tables.append(ls)
 full=[]
 for ls in tables:
  full.append(ls[0]|(ls[0]^ls[1])|ls[1]) # not correct full: union misses zeros both; use points
 print('built',t,flush=True)
 for i in range(300000):
  fs=[]
  for ls in tables:
   v=0
   for j in range(random.choice([2,2,3,4])):
    a,b=random.sample(ls,2);v^=a&b
   fs.append(v)
  w=(fs[0]^fs[1]).bit_count()
  if 256<w<320 and w not in known:
   print('NEW',t,w,flush=True);pickle.dump(fs,open('newfamily.pkl','wb'));quit()

